(() => {
'use strict';
const app=document.getElementById('app'),KEY=new URLSearchParams(location.search).has('qa')?'noesis-qa-v1':'noesis-progress-v1',VERSION=1;
const $=s=>app.querySelector(s),$$=s=>Array.from(app.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const math=(f,display=false)=>{try{return window.katex?katex.renderToString(String(f),{displayMode:display,throwOnError:false,strict:'ignore',trust:false}):esc(f)}catch{return esc(f)}};
const rich=s=>String(s??'').split(/(\$[^$]+\$)/g).map(t=>t.startsWith('$')&&t.endsWith('$')?math(t.slice(1,-1)):esc(t)).join('');
const icon=name=>({map:'◈',lesson:'▤',lab:'⌁',review:'↻',atlas:'ƒ',settings:'⚙'}[name]||'◇');
const num=(v,d=1)=>Number(v).toFixed(d),byId=id=>LESSONS.find(l=>l.id===id),world=id=>WORLDS.find(w=>w.id===id),inWorld=id=>LESSONS.filter(l=>l.world===id);
const today=()=>new Date().toLocaleDateString('en-CA');
const blank=()=>({version:VERSION,xp:0,records:{},questionXP:[],badges:[],labBadges:[],history:[],settings:{sound:false,dense:true},lastLesson:null});
let profile=blank(),storageOK=true;
function validateProfile(data){if(!data||typeof data!=='object'||data.version!==VERSION||!data.records||typeof data.records!=='object'||Array.isArray(data.records))throw Error('Formato de bitácora incompatible.');const out=blank();out.xp=Number.isFinite(data.xp)?Math.max(0,Math.min(1e7,Math.floor(data.xp))):0;out.questionXP=Array.isArray(data.questionXP)?data.questionXP.filter(v=>typeof v==='string'&&/^[a-z]+-\d+:\d+$/.test(v)).slice(0,20000):[];out.badges=Array.isArray(data.badges)?data.badges.filter(id=>!!world(id)):[];out.labBadges=Array.isArray(data.labBadges)?data.labBadges.filter(id=>typeof id==='string'&&Object.hasOwn(VISUALS,id)):[];out.lastLesson=byId(data.lastLesson)?data.lastLesson:null;out.settings={sound:data.settings?.sound===true,dense:data.settings?.dense===true};out.history=Array.isArray(data.history)?data.history.filter(h=>h&&typeof h.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(h.date)&&Number.isFinite(h.correct)&&Number.isFinite(h.total)&&h.total>0&&h.correct>=0&&h.correct<=h.total).slice(-300).map(h=>({date:h.date,correct:h.correct,total:h.total,kind:['lesson','world','review','diagnostic'].includes(h.kind)?h.kind:'lesson'})):[];for(const [id,r]of Object.entries(data.records)){if(!byId(id)||!r||typeof r!=='object')continue;out.records[id]={mastered:r.mastered===true,seen:r.seen===true,score:Number.isFinite(r.score)?Math.max(0,Math.min(1,r.score)):0,attempts:Number.isFinite(r.attempts)?Math.max(0,Math.min(1e6,Math.floor(r.attempts))):0,wrong:Array.isArray(r.wrong)?r.wrong.filter(i=>Number.isInteger(i)&&i>=0&&i<4):[],due:Number.isFinite(r.due)?Math.max(0,r.due):0,interval:Number.isFinite(r.interval)?Math.max(1,Math.min(180,r.interval)):1};}return out;}
try{const raw=localStorage.getItem(KEY);if(raw)profile=validateProfile(JSON.parse(raw));}catch{storageOK=false;}
let state={view:'map',world:'foundations',lesson:profile.lastLesson||LESSONS[0]?.id,tab:'brief',lab:'function',atlasQuery:'',route:'all'},session=null,toastTimer,audioCtx;
function save(){try{localStorage.setItem(KEY,JSON.stringify(profile));storageOK=true;}catch{storageOK=false;toast('El navegador no permite guardar. Exporta tu bitácora para conservarla.');}}
function record(id){return profile.records[id]||(profile.records[id]={mastered:false,seen:false,score:0,attempts:0,wrong:[],due:0,interval:1});}
const totalMastered=()=>Object.values(profile.records).filter(r=>r.mastered).length;
const worldMastered=id=>inWorld(id).filter(l=>profile.records[l.id]?.mastered).length;
const percent=id=>inWorld(id).length?Math.round(worldMastered(id)/inWorld(id).length*100):0;
const dueLessons=()=>LESSONS.filter(l=>{const r=profile.records[l.id];return r&&(r.wrong.length||r.mastered&&r.due<=Date.now())});
function toast(s){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3300);}
function sound(correct){if(!profile.settings.sound)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.setValueAtTime(correct?640:240,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(correct?960:180,audioCtx.currentTime+.1);gain.gain.setValueAtTime(.04,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.2);osc.connect(gain).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.21);}catch{}}
function go(view,extra={}){if(session&&!session.finished&&state.view==='quiz'&&view!=='quiz'){if(!confirm('Salir del desafío actual? Las respuestas ya resueltas conservarán sus XP; el dominio requiere terminar.'))return;session=null;}Object.assign(state,{view},extra);location.hash=view==='lesson'?`mission/${state.lesson||state.world}`:view==='lab'?`lab/${state.lab}`:view;render();window.scrollTo({top:0,behavior:'instant'});return true;}
function openLesson(id){const l=byId(id);if(!l)return;if(go('lesson',{world:l.world,lesson:id,tab:'brief'})){record(id).seen=true;profile.lastLesson=id;save();}}
function nextMission(){const last=byId(profile.lastLesson);if(last&&!profile.records[last.id]?.mastered)return last;const route=['foundations','probability','statistics','bayesian','information','linear','differential','multivariate','variational','generative','decision','active','integral','dynamics'];for(const wid of route){const l=inWorld(wid).find(l=>!profile.records[l.id]?.mastered);if(l)return l;}return LESSONS[0];}
function shell(content){const pc=LESSONS.length?Math.round(totalMastered()/LESSONS.length*100):0;document.body.classList.toggle('dense',profile.settings.dense);app.innerHTML=`<aside class="sidebar"><a class="brand" href="#map" aria-label="Nóesis, mapa de mundos"><span class="brand-mark">N</span><span>NÓESIS<small>ENIGMA / MATH ENGINE</small></span></a><div class="nav-label">NAVEGACIÓN</div><nav>${[['map','Mapa de mundos'],['lesson','Misiones'],['lab','Laboratorio'],['review','Repaso'],['atlas','Atlas matemático']].map(([id,label])=>`<button class="nav-item ${state.view===id||id==='lesson'&&state.view==='quiz'?'selected':''}" data-view="${id}" title="${label}" aria-label="${label}" ${state.view===id?'aria-current="page"':''}><span aria-hidden="true">${icon(id)}</span>${label}${id==='review'&&dueLessons().length?`<b class="count">${dueLessons().length}</b>`:''}</button>`).join('')}</nav><div class="side-route"><span class="eyebrow">COORDENADAS FINALES</span><p>Active inference</p><span class="mini-formula">F → G → agencia</span><div class="progress-track" role="progressbar" aria-label="Dominio de la ruta" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pc}"><i style="width:${pc}%"></i></div><small>${totalMastered()} / ${LESSONS.length} misiones dominadas</small></div><button class="nav-item bottom ${state.view==='settings'?'selected':''}" data-view="settings" title="Bitácora y ajustes" aria-label="Bitácora y ajustes"><span>⚙</span>Bitácora y ajustes</button><div class="system-line"><span class="status-dot"></span>${storageOK?'GUARDADO LOCAL':'MEMORIA TEMPORAL'} <span>v1.0</span></div></aside><main><header class="topbar"><span>MATEMÁTICA / <strong>${{map:'MAPA DE MUNDOS',lesson:'MISIÓN',quiz:'DESAFÍO',lab:'LABORATORIO',review:'REPASO',atlas:'ATLAS',settings:'BITÁCORA'}[state.view]}</strong></span><div class="top-stats"><span class="keycap">∞</span><span>Sin vidas. Sin prisa.</span><span class="xp">${profile.xp.toLocaleString('es-CL')} XP</span></div></header>${content}<footer><span>NÓESIS / DE PRIMEROS PRINCIPIOS A INFERENCIA ACTIVA</span><span>${WORLDS.length} MUNDOS · ${LESSONS.length} MISIONES · ${LESSONS.reduce((a,l)=>a+l.questions.length,0)} DESAFÍOS</span></footer></main>`;bindCommon();renderMath();}
function renderMath(){app.querySelectorAll('[data-math]').forEach(el=>el.innerHTML=math(el.dataset.math,true));}
function bindCommon(){$$('[data-view]').forEach(b=>b.onclick=()=>{const view=b.dataset.view;if(view==='lesson'){const l=byId(state.lesson)||nextMission();l?openLesson(l.id):go('map');}else go(view)});$$('[data-world]').forEach(b=>b.onclick=()=>{const w=b.dataset.world,l=inWorld(w).find(l=>!profile.records[l.id]?.mastered)||inWorld(w)[0];if(l)openLesson(l.id)});$$('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));$$('[data-lab]').forEach(b=>b.onclick=()=>go('lab',{lab:b.dataset.lab}));$$('[data-start]').forEach(b=>b.onclick=()=>startQuiz(b.dataset.start,b.dataset.target));$$('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});}
function horizon(){return `<svg viewBox="0 0 480 230" class="curve" role="img" aria-label="La creencia posterior como distribución"><defs><linearGradient id="fill" x2="0" y2="1"><stop stop-color="#79dce8" stop-opacity=".25"/><stop offset="1" stop-color="#79dce8" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map(y=>`<path d="M0 ${y}H480" class="gridline"/>`).join('')}${[60,140,220,300,380,460].map(x=>`<path d="M${x} 0V220" class="gridline"/>`).join('')}<path d="M0 180Q130 180 190 110Q250 0 310 110Q370 180 480 180V220H0Z" fill="url(#fill)"/><path d="M0 180Q130 180 190 110Q250 0 310 110Q370 180 480 180" fill="none" stroke="#79dce8" stroke-width="2.5"/><path d="M250 30V210" stroke="#c7f36b" stroke-dasharray="4 7"/><circle cx="250" cy="55" r="5" fill="#c7f36b"/><text x="264" y="40" fill="#c7f36b">q(s)</text></svg>`;}
function mapPage(){const next=nextMission(),nextw=next&&world(next.world);return `<section class="page-head"><div><span class="eyebrow green">EXPEDICIÓN ${String(profile.history.length+1).padStart(3,'0')}</span><h1>Del símbolo a la agencia<span class="cursor">_</span></h1><p>Una idea. Una intuición. Un desafío. Conecta las piezas.</p></div>${next?`<button class="btn primary" data-lesson="${next.id}">${profile.lastLesson?'Continuar misión':'Entrar al mundo 01'} <span>▶</span></button>`:''}</section><section class="mission-strip"><div><span class="tag">TRONCO HACIA BAYES</span><strong>Lenguaje → Probabilidad → Bayes → Energía libre</strong></div><span class="muted">Exploración libre · dominio verificable</span></section><div class="dashboard-grid"><section class="panel map-panel"><div class="panel-head"><div><span class="eyebrow">CARTOGRAFÍA DEL CONOCIMIENTO</span><h2>14 mundos. Un sistema.</h2></div><span class="legend"><i class="green-dot"></i>Tronco <i class="cyan-dot"></i>Continuo <i class="orange-dot"></i>Agencia</span></div><div class="map-filter segmented" aria-label="Ramas del currículo">${[['all','Todos'],['discrete','Ruta discreta'],['continuous','Ruta continua']].map(([id,t])=>`<button class="${state.route===id?'active':''}" data-route="${id}" aria-pressed="${state.route===id}">${t}</button>`).join('')}</div><div class="world-map">${WORLDS.map(w=>{const dim=state.route!=='all'&&w.route!=='both'&&w.route!==state.route;return `<button class="world-node ${nextw?.id===w.id?'current':''} ${percent(w.id)===100?'complete':''} ${dim?'dimmed':''}" data-world="${w.id}" style="--world-color:${w.color}" aria-label="${w.n}. ${w.name}. ${worldMastered(w.id)} de ${inWorld(w.id).length} misiones dominadas"><span class="world-meta">${w.n} <span>${percent(w.id)===100?'DOMINADO':w.route==='continuous'?'CONTINUO':w.id==='active'?'DESTINO':`${inWorld(w.id).length} MISIONES`}</span></span><span class="world-symbol">${percent(w.id)===100?'✓':w.symbol}</span><strong>${w.name}</strong><span class="world-tag">${w.tag}</span><span class="node-progress"><i style="width:${percent(w.id)}%"></i></span></button>`}).join('')}</div><div class="map-foot"><span>◇ Todo es explorable. Cada mundo señala sus prerrequisitos.</span><button class="text-button" data-view="atlas">Ver dependencias</button></div></section><aside class="mission-panel panel"><div class="panel-head"><span class="eyebrow">TU SIGUIENTE MISIÓN</span><span class="tag green">${nextw?.n||'01'} / ${nextw?.symbol||'P'}</span></div><div class="mission-content"><span class="mission-number">${nextw?.name||'Pre cálculo'} · ${next?.minutes||6} MIN</span><h2>${esc(next?.title||'Aprender a leer el universo.')}</h2><p>${esc(next?.subtitle||'Domina la notación. Una ecuación deja de ser una pared y se convierte en un mapa.')}</p>${horizon()}<div class="mission-quote"><span>EL HORIZONTE</span><p>Un agente cambia sus creencias para entender el mundo y actúa para cambiarlo.</p></div><div class="mission-detail"><span>◷ ${next?.minutes||6} min</span><span>4 desafíos · hasta 90 XP</span></div>${next?`<button class="btn primary full" data-lesson="${next.id}">Iniciar misión <span>▶</span></button>`:''}</div></aside></div><section class="bottom-grid"><article class="mini-panel"><span class="eyebrow">01 / COMPRENDE</span><h3>Información con estructura.</h3><p>Principio, fórmula, derivación y conexión. Lo necesario en un solo lugar.</p></article><article class="mini-panel"><span class="eyebrow">02 / EXPERIMENTA</span><h3>Haz visible la intuición.</h3><p>Mueve parámetros. Observa qué cambia. Anticipa antes de calcular.</p></article><article class="mini-panel"><span class="eyebrow">03 / DEMUESTRA</span><h3>Avanza por dominio.</h3><p>Prueba lo que sabes, salta lo conocido y repara errores con feedback.</p></article></section>`;}
function lessonPage(){const l=byId(state.lesson)||nextMission();if(!l)return '<p>Preparando las misiones.</p>';state.lesson=l.id;state.world=l.world;const w=world(l.world),ls=inWorld(l.world),r=profile.records[l.id],ix=ls.indexOf(l),gaps=w.prereq.filter(id=>percent(id)<100);return `<section class="world-heading"><div class="world-heading-symbol" style="color:${w.color}">${w.symbol}</div><div><span class="eyebrow" style="color:${w.color}">MUNDO ${w.n} / ${esc(w.tag).toUpperCase()}</span><h1>${w.name}</h1><p>${w.desc}</p></div><button class="btn" data-view="map">Mapa</button></section><div class="lesson-layout"><aside class="lesson-list panel"><div class="panel-head"><span class="eyebrow">${worldMastered(w.id)} / ${ls.length} DOMINADAS</span></div>${ls.map((item,i)=>`<button class="lesson-item ${l.id===item.id?'active':''}" data-lesson="${item.id}"><span class="lesson-index">${profile.records[item.id]?.mastered?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${esc(item.title)}</strong><small>${item.minutes} min · ${profile.records[item.id]?.mastered?'dominio':'4 desafíos'}</small></span></button>`).join('')}<div class="world-test"><span class="eyebrow">¿YA LO SABES?</span><p>Demuestra dominio y salta el mundo. ${ls.length} preguntas, sin pistas.</p><button class="btn full" data-start="world" data-target="${w.id}">Prueba de salto</button></div></aside><div class="lesson-main"><div class="lesson-title"><span class="eyebrow green">MISIÓN ${w.n}.${String(ix+1).padStart(2,'0')} ${r?.mastered?'· DOMINADA':''}</span><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p></div>${gaps.length?`<div class="prereq-note"><span>Base recomendada:</span> ${gaps.map(id=>`<button class="text-button" data-world="${id}">${world(id).name}</button>`).join(' · ')}<small>Explora libremente; vuelve si encuentras un salto.</small></div>`:''}<div class="lesson-tabs" role="tablist">${[['brief','01 · Principios'],['derivation','02 · Derivación'],['visual','03 · Intuición visual']].map(([id,t])=>`<button role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}</div><div class="lesson-content">${state.tab==='brief'?`<div class="intuition-card"><span class="eyebrow">LA IDEA EN UNA LÍNEA</span><p>${rich(l.intuition)}</p></div><div class="core-grid">${l.core.map((c,i)=>`<article class="concept-card"><span class="concept-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(c.label)}</h3><p>${rich(c.body)}</p>${c.formula?`<div class="formula">${math(c.formula,true)}</div>`:''}</article>`).join('')}</div><div class="worked-example"><span class="eyebrow cyan">EJEMPLO MÍNIMO</span><h3>${rich(l.example.problem)}</h3><p>${rich(l.example.solution)}</p></div><div class="pitfall"><strong>△ Punto de precisión</strong><p>${rich(l.pitfall)}</p></div>`:state.tab==='derivation'?`<div class="intuition-card"><span class="eyebrow">RECONSTRUYE EL ARGUMENTO</span><p>Cada línea debe seguir de la anterior. Lee la razón, luego oculta el resultado y trata de recuperarlo.</p></div><div class="derivation-steps">${l.derivation.map((s,i)=>`<article><span class="step-index">${i+1}</span><div><p>${rich(s.reason)}</p><div class="formula">${math(s.formula,true)}</div></div></article>`).join('')}</div><div class="worked-example"><span class="eyebrow">APLICACIÓN</span><h3>${rich(l.example.problem)}</h3><p>${rich(l.example.solution)}</p></div>`:`<div class="panel visual-card"><div class="panel-head"><div><span class="eyebrow">LABORATORIO VINCULADO</span><h3>${VISUALS[l.visual]?.name||'Exploración visual'}</h3></div><button class="text-button" data-lab="${l.visual}">Abrir laboratorio</button></div><div id="lesson-viz" class="viz-body"></div></div>`}</div><div class="bridge-card"><span class="eyebrow">CONEXIÓN / ACTIVE INFERENCE</span><p>${rich(l.bridge)}</p></div><div class="lesson-actions"><div><strong>Convierte comprensión en dominio.</strong><p>4 desafíos · 3 aciertos sin ayuda para acreditar · pistas disponibles</p></div><button class="btn primary" data-start="lesson" data-target="${l.id}">${r?.mastered?'Volver a entrenar':'Entrar al desafío'} <span>▶</span></button></div><div class="lesson-source">Fuentes: ${(l.references||[]).map(id=>SOURCES.find(s=>s.id===id)?.title).filter(Boolean).map(esc).join(' · ')}</div></div></div>`;}
function labPage(){if(!Object.hasOwn(VISUALS,state.lab))state.lab='function';const def=VISUALS[state.lab],field=FIELD_MISSIONS[state.lab];return `<section class="page-head"><div><span class="eyebrow green">GEOMETRÍA / EXPERIMENTACIÓN</span><h1>Laboratorio de intuición</h1><p>Predice. Mueve un parámetro. Explica lo que cambia.</p></div><span class="tag">${Object.keys(VISUALS).length} SISTEMAS INTERACTIVOS</span></section><div class="lab-layout"><aside class="lab-selector panel">${Object.entries(VISUALS).map(([id,v])=>`<button class="lab-option ${state.lab===id?'active':''}" data-lab="${id}"><span style="color:${world(v.world)?.color}">${world(v.world)?.symbol}</span><div><strong>${v.name}</strong><small>${world(v.world)?.name}</small></div></button>`).join('')}</aside><div><section class="panel visual-card"><div class="panel-head"><div><span class="eyebrow">${world(def.world)?.name.toUpperCase()}</span><h2>${def.name}</h2><p>${def.question}</p></div><span class="lab-live">INTERACTIVO</span></div><div id="lab-viz" class="viz-body"></div></section><section class="field-mission panel"><div><span class="eyebrow orange">CONTRATO DE CAMPO / +40 XP</span><h3>${field.title} ${profile.labBadges.includes(state.lab)?'✓':''}</h3><p>${field.goal}</p></div><div class="field-actions"><button class="btn primary" id="verify-field">Verificar objetivo</button><button class="text-button" id="field-clue">Pista de campo</button></div><div class="field-feedback" id="field-feedback" aria-live="polite"></div></section><div class="lab-linked"><span class="eyebrow">MISIONES RELACIONADAS</span>${LESSONS.filter(l=>l.visual===state.lab).map(l=>`<button class="related-chip" data-lesson="${l.id}">${esc(l.title)}</button>`).join('')}</div></div></div>`;}
function shuffle(a){const copy=a.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
function startQuiz(kind,target){let items=[];if(kind==='lesson'){const l=byId(target);if(!l)return;items=l.questions.map((q,i)=>({q,lesson:l.id,qi:i}));}else if(kind==='world'){items=inWorld(target).map(l=>({q:l.questions[3],lesson:l.id,qi:3}));}else if(kind==='diagnostic'){items=['foundations','linear','probability','statistics','bayesian','information','variational','active'].map(w=>{const l=inWorld(w)[0];return l?{q:l.questions[2],lesson:l.id,qi:2}:null}).filter(Boolean);}else{items=dueLessons().flatMap(l=>{const r=profile.records[l.id];const indices=r.wrong.length?r.wrong:[Math.floor(Math.random()*4)];return indices.map(i=>({q:l.questions[i],lesson:l.id,qi:i}));});items=shuffle(items).slice(0,8);if(!items.length){toast('No hay repaso pendiente. Abre una misión para entrenar.');return;}}items=items.map(item=>{if(item.q.type==='choice'){const order=shuffle(item.q.options.map((_,i)=>i));return {...item,order};}return item;});session={kind,target,items,index:0,answers:[],correct:0,unassisted:0,assisted:false,answered:false,feedback:null,selection:null,finished:false,start:Date.now()};state.view='quiz';render();window.scrollTo({top:0,behavior:'instant'});}
function quizPage(){if(!session){state.view='map';return mapPage();}if(session.finished)return resultPage();const item=session.items[session.index],q=item.q,l=byId(item.lesson),w=world(l.world);return `<div class="quiz-top"><button class="text-button" id="exit-quiz">× Salir del desafío</button><span class="eyebrow">${session.kind==='world'?'PRUEBA DE SALTO':session.kind==='review'?'REACTIVACIÓN':session.kind==='diagnostic'?'DIAGNÓSTICO':'DESAFÍO DE DOMINIO'} / ${session.index+1} DE ${session.items.length}</span><span class="green">${session.correct} aciertos</span></div><div class="quiz-progress">${session.items.map((_,i)=>`<i class="${i<session.index?session.answers[i]?.correct?'correct':'wrong':i===session.index?'current':''}"></i>`).join('')}</div><section class="quiz-card panel"><div class="quiz-context"><span class="tag">${w.symbol} / ${w.name}</span><span>${esc(l.title)}</span></div><h1>${rich(q.prompt)}</h1>${q.formula?`<div class="question-formula">${math(q.formula,true)}</div>`:''}<div class="answer-zone">${q.type==='choice'?`<div class="answers">${item.order.map((oi,i)=>`<button class="answer ${session.selection===oi?'chosen':''} ${session.answered&&oi===q.answer?'correct-answer':''} ${session.answered&&session.selection===oi&&oi!==q.answer?'wrong-answer':''}" data-answer="${oi}" ${session.answered?'disabled':''}><span class="answer-key">${i+1}</span><span>${rich(q.options[oi])}</span>${session.answered&&oi===q.answer?'<span class="answer-check">✓</span>':''}</button>`).join('')}</div>`:`<form id="numeric-form"><label for="numeric-answer">Tu respuesta numérica</label><div class="numeric-row"><input id="numeric-answer" inputmode="decimal" autocomplete="off" placeholder="Número o fracción, ej. 0,5 o 1/2" ${session.answered?'disabled':''} value="${esc(session.numeric||'')}"><button class="btn primary" ${session.answered?'disabled':''}>Comprobar</button></div><small>Tolerancia: ${q.tolerance??.01}. Se aceptan coma decimal y fracciones.</small></form>`}</div>${session.assisted&&!session.answered?`<div class="hint-box"><strong>Pista</strong><p>${rich(q.hint)}</p></div>`:''}${session.answered?`<div class="feedback ${session.feedback.correct?'success':'repair'}" role="status"><strong>${session.feedback.correct?session.assisted?'Correcto · con apoyo':'Correcto · sin ayuda':'Reconstruye este paso'}</strong>${q.type==='numeric'?`<p>Respuesta: <strong>${esc(q.answer)}</strong></p>`:''}<p>${rich(q.explanation)}</p>${session.assisted?'<small>Esta respuesta es práctica; no suma dominio independiente.</small>':''}</div>`:''}<div class="quiz-actions"><div>${session.kind!=='world'&&!session.answered?`<button class="text-button" id="hint-btn" ${session.assisted?'disabled':''}>${session.assisted?'Pista utilizada':'Mostrar una pista'}</button>`:'<span class="muted">Sin ayuda = evidencia de dominio</span>'}</div>${session.answered?`<button class="btn primary" id="next-question">${session.index+1===session.items.length?'Ver resultado':'Siguiente desafío'} <span>▶</span></button>`:'<span class="keyboard-help">Teclas 1–4 · Enter para continuar</span>'}</div></section>`;}
function parseNumber(str){const clean=String(str).trim().replaceAll(',','.').replaceAll('−','-').replaceAll(' ','');if(/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[-+]?\d+)?$/i.test(clean))return Number(clean);const m=clean.match(/^([-+]?(?:\d+(?:\.\d*)?|\.\d+))\/([-+]?(?:\d+(?:\.\d*)?|\.\d+))$/);return m&&+m[2]!==0?+m[1]/+m[2]:NaN;}
function answer(value){if(!session||session.answered||session.finished)return;const item=session.items[session.index],q=item.q;let correct;if(q.type==='numeric'){const v=parseNumber(value);if(!Number.isFinite(v)){toast('Escribe un número finito o una fracción con denominador distinto de cero.');return;}correct=Math.abs(v-q.answer)<=(q.tolerance??.01);session.numeric=value;}else{session.selection=Number(value);correct=session.selection===q.answer;}session.answered=true;session.feedback={correct};if(correct){session.correct++;if(!session.assisted)session.unassisted++;const key=`${item.lesson}:${item.qi}`;if(!profile.questionXP.includes(key)&&session.kind!=='diagnostic'){profile.xp+=session.assisted?5:10;profile.questionXP.push(key);save();}}session.answers.push({lesson:item.lesson,qi:item.qi,correct,assisted:session.assisted});sound(correct);render();$('#next-question')?.focus();}
function nextQuestion(){if(!session?.answered)return;if(session.index+1>=session.items.length){finishQuiz();return;}session.index++;session.assisted=false;session.answered=false;session.feedback=null;session.selection=null;session.numeric='';render();$('#numeric-answer')?.focus();}
function finishQuiz(){session.finished=true;const score=session.unassisted/session.items.length,wasMastered=totalMastered();if(session.kind==='lesson'){const r=record(session.target);r.attempts++;r.seen=true;r.score=Math.max(r.score,score);r.wrong=session.answers.filter(a=>!a.correct||a.assisted).map(a=>a.qi);if(score>=.75){if(!r.mastered)profile.xp+=50;r.mastered=true;r.interval=1;r.due=Date.now()+864e5;}else r.due=Date.now();}else if(session.kind==='world'&&score>=.85){for(const l of inWorld(session.target)){const r=record(l.id);if(!r.mastered)profile.xp+=50;r.mastered=true;r.seen=true;r.score=1;r.wrong=[];r.due=Date.now()+864e5;}if(!profile.badges.includes(session.target)){profile.badges.push(session.target);profile.xp+=100;}}else if(session.kind==='review'){for(const id of new Set(session.answers.map(a=>a.lesson))){const r=record(id),answers=session.answers.filter(a=>a.lesson===id);for(const a of answers){if(a.correct&&!a.assisted)r.wrong=r.wrong.filter(i=>i!==a.qi);else if(!r.wrong.includes(a.qi))r.wrong.push(a.qi);}if(r.wrong.length||answers.some(a=>!a.correct||a.assisted)){r.interval=1;r.due=Date.now();}else{r.interval=Math.min(60,Math.round(r.interval*2));r.due=Date.now()+r.interval*864e5;}}}session.newMastery=totalMastered()-wasMastered;profile.history.push({date:today(),correct:session.correct,total:session.items.length,kind:session.kind});profile.history=profile.history.slice(-300);save();render();}
function resultPage(){const passed=session.kind==='world'?session.unassisted/session.items.length>=.85:session.unassisted/session.items.length>=.75,kind=session.kind;const title=kind==='diagnostic'?'Tu punto de partida':kind==='review'?'Recuperación completada':passed?'Dominio demostrado.':'Intuición en construcción.';const next=nextMission();return `<section class="result-card panel"><span class="result-symbol ${passed?'green':'cyan'}">${passed?'◈':'⌁'}</span><span class="eyebrow">${kind==='diagnostic'?'DIAGNÓSTICO':kind==='world'?'PRUEBA DE SALTO':'RESULTADO'}</span><h1>${title}</h1><div class="result-stats"><div><strong>${session.correct}/${session.items.length}</strong><span>aciertos totales</span></div><div><strong>${session.unassisted}/${session.items.length}</strong><span>sin ayuda</span></div><div><strong>${Math.max(1,Math.round((Date.now()-session.start)/60000))} min</strong><span>tiempo de práctica</span></div></div><p>${kind==='diagnostic'?'Este diagnóstico orienta tu exploración; no acredita mundos completos. Usa las pruebas de salto para demostrar lo que ya manejas.':kind==='world'?(passed?'Mundo acreditado. Sus misiones quedan disponibles para volver a entrenar.':'Para acreditar el mundo necesitas 85% sin ayuda. Cada error señala una misión concreta para revisar.'):kind==='review'?'Cada recuerdo sin ayuda amplía el intervalo de repaso. Los errores vuelven a la cola.':passed?'La misión queda acreditada. Volverás a verla en el repaso para consolidar.':'Necesitas 3 de 4 respuestas sin ayuda para acreditar. Ya tienes el feedback para reconstruir lo que falta.'}</p><div class="result-review">${session.answers.map((a,i)=>`<button data-lesson="${a.lesson}"><span class="${a.correct&&!a.assisted?'green':'orange'}">${a.correct?a.assisted?'◇':'✓':'△'}</span><span>${esc(byId(a.lesson).title)}<small>${a.correct?a.assisted?'con pista':'sin ayuda':'revisar el razonamiento'}</small></span><span class="muted">${i+1}</span></button>`).join('')}</div><div class="result-actions">${next?`<button class="btn primary" data-lesson="${next.id}">Continuar ruta <span>▶</span></button>`:''}<button class="btn" id="retry-quiz">Repetir desafío</button><button class="text-button" id="result-map">Mapa de mundos</button></div></section>`;}
function reviewPage(){const due=dueLessons(),done=totalMastered();return `<section class="page-head"><div><span class="eyebrow green">MEMORIA / CONSOLIDACIÓN</span><h1>Lo que recuerdas, lo que dominas.</h1><p>Recupera ideas antes de releerlas. El error deja una coordenada para volver.</p></div>${due.length?'<button class="btn primary" data-start="review">Iniciar repaso <span>▶</span></button>':''}</section><div class="review-summary"><div>${due.length}<span>misiones para reactivar</span></div><div>${done}<span>misiones dominadas</span></div><div>${profile.history.reduce((a,h)=>a+h.total,0)}<span>respuestas realizadas</span></div></div>${due.length?`<div class="review-list">${due.map(l=>{const r=profile.records[l.id];return `<article class="panel"><span style="color:${world(l.world).color}" class="review-symbol">${world(l.world).symbol}</span><div><span class="eyebrow">${world(l.world).name}</span><h3>${esc(l.title)}</h3><p>${r.wrong.length?`${r.wrong.length} paso${r.wrong.length===1?'':'s'} para reconstruir`:'Recuperación espaciada · sin ayuda'}</p></div><button class="btn" data-lesson="${l.id}">Reconstruir</button></article>`;}).join('')}</div>`:`<section class="empty-state panel"><span>◈</span><h2>${done?'Todo al día.':'Tu primera misión te espera.'}</h2><p>${done?'Las misiones dominadas reaparecerán cuando venza su intervalo de repaso.':'Resuelve una misión. Aquí aparecerán errores y conceptos que conviene recuperar.'}</p><button class="btn primary" data-lesson="${nextMission()?.id}">Continuar ruta</button></section>`}<div class="review-explain"><h3>Una regla transparente.</h3><p>Una misión acreditada vuelve al día siguiente. Cada recuperación correcta sin ayuda duplica el intervalo hasta 60 días. Un error vuelve a hoy. Las preguntas del banco se reutilizan: el dominio aquí es una señal de estudio, no una certificación externa.</p></div>`;}
const glossary=[
['Conjunto / pertenencia','x\\in A','x es un elemento de A. No confundir pertenencia con inclusión A⊆B.','foundations'],['Indicador / tus apuntes','\\mathbf1_A(x)\\in\\{0,1\\},\\quad P(A\\mid I)=\\mathbb E[\\mathbf1_A\\mid I]','El Q(A) de tus apuntes equivale a 1_A; q se reserva para creencias variacionales.','probability'],['Composición','(f\\circ g)(x)=f(g(x))','La salida de g debe pertenecer al dominio de f.','foundations'],['Logaritmo','\\ln(ab)=\\ln a+\\ln b,\\quad a,b>0','Convierte productos de probabilidades en sumas; la base e da nats.','foundations'],['Derivada','f\'(x)=\\lim_{h\\to0}\\frac{f(x+h)-f(x)}h','Tasa local si el límite existe; diferenciabilidad implica continuidad.','differential'],['Integral / expectativa','\\mathbb E[f(X)]=\\int f(x)p(x)\\,dx','Para variables continuas con densidad; la expectativa debe existir.','integral'],['Gradiente','\\nabla f=(\\partial_1 f,\\ldots,\\partial_n f)^\\top','Dirección de máximo aumento bajo geometría euclídea.','multivariate'],['Taylor / Laplace','f(x)\\approx f(\\mu)+\\nabla f(\\mu)^\\top(x-\\mu)+\\tfrac12(x-\\mu)^\\top H(x-\\mu)','Aproximación local para f suave; la curvatura define precisión local si es adecuada.','multivariate'],['Bayes','p(s\\mid o)=\\frac{p(o\\mid s)p(s)}{p(o)}','Evidencia p(o)>0; integra o suma sobre los estados ocultos para normalizar.','bayesian'],['Evidencia','p(o)=\\sum_s p(o\\mid s)p(s)','Estados discretos. Para estados continuos, sustituye suma por integral.','bayesian'],['Factor de Bayes','BF_{12}=\\frac{p(o\\mid M_1)}{p(o\\mid M_2)}','Multiplica odds entre modelos. El likelihood/evidencia de tus apuntes es otro factor de actualización.','bayesian'],['Densidad ≠ probabilidad','P(a<X<b)=\\int_a^b p_X(x)\\,dx','Con una distribución continua sin átomos, P(X=x)=0. Una densidad puede superar 1.','probability'],['Varianza / precisión','\\Pi=\\Sigma^{-1},\\quad \\operatorname{Var}(X)=\\mathbb E[(X-\\mu)^2]','Σ debe ser invertible para usar su inversa; mayor precisión significa menor incertidumbre del modelo.','linear'],['Normalización A / B','\\sum_o A_{os}=1,\\quad\\sum_{s\'}B^u_{s\'s}=1','A: observaciones×estados. B: siguiente estado×estado actual; columnas condicionales.','generative'],['Entropía','H[p]=-\\sum_x p(x)\\ln p(x)','Convención 0 ln 0=0. Discreta; la entropía diferencial no hereda todas sus propiedades.','information'],['KL dirigida','D_{\\mathrm{KL}}(q\\Vert p)=\\mathbb E_q[\\ln q-\\ln p]\\ge0','Si q asigna masa donde p=0, la divergencia es infinita. No es una distancia simétrica.','information'],['Información mutua','I(S;O)=H(O)-H(O\\mid S)','Incertidumbre de una observación no equivale a información sobre un estado.','information'],['Energía libre variacional','F[q]=\\mathbb E_q[\\ln q(s)-\\ln p(o,s)]','Datos o ya observados; no es energía metabólica. Depende de q y del modelo.','variational'],['Cota variacional','F=D_{\\mathrm{KL}}(q\\Vert p(s\\mid o))-\\ln p(o)\\ge-\\ln p(o)','Igualdad al alcanzar el posterior exacto. F puede ser negativo con evidencia continua de densidad >1.','variational'],['Complejidad / exactitud','F=D_{\\mathrm{KL}}(q\\Vert p(s))-\\mathbb E_q[\\ln p(o\\mid s)]','Exactitud aquí es log verosimilitud esperada; no porcentaje de clasificaciones correctas.','variational'],['ELBO','\\operatorname{ELBO}=-F\\le\\ln p(o)','Maximizar ELBO equivale a minimizar F para el mismo modelo y datos.','variational'],['Preferencias C','P_C(o)=\\operatorname{softmax}(C)_o','En esta app C son logits. El libro a veces llama C al vector de probabilidades: traduce la convención.','decision'],['G / riesgo y ambigüedad','G(\\pi)=D_{\\mathrm{KL}}(q(o\\mid\\pi)\\Vert P_C(o))+\\mathbb E_{q(s\\mid\\pi)}[H[p(o\\mid s)]]','Convención de preferencias sobre observaciones, un paso. G es prospectiva; F usa datos observados.','active'],['G / valor epistémico','G(\\pi)=-I_q(S;O\\mid\\pi)-\\mathbb E_{q(o\\mid\\pi)}[\\ln P_C(o)]','Equivalente bajo la misma distribución predictiva y preferencias sobre observaciones del laboratorio.','active'],['Posterior de políticas','q(\\pi)=\\operatorname{softmax}(\\ln E-F(\\pi)-G(\\pi))','E es prior habitual; el F de políticas representa evidencia del pasado observado. Escalas de precisión requieren convención explícita.','active'],['Descenso de gradiente','\\mu_{t+1}=\\mu_t-\\eta\\nabla_\\mu F','El tamaño η importa; descenso no garantiza mínimo global.','multivariate'],['Aprendizaje Dirichlet','a_{os}\\leftarrow a_{os}+o_o s_s','Conteos esperados: outer(o,s), coherentes con orientación observación×estado.','generative'],['Ornstein–Uhlenbeck','dx=-kx\\,dt+\\sigma\\,dW_t','Para k>0 existe estado estacionario gaussiano de varianza σ²/(2k).','dynamics'],['Filtro / coordenadas generalizadas','\\dot{\\widetilde\\mu}=\\mathcal D\\widetilde\\mu-\\nabla_{\\widetilde\\mu}F','Diferencia el operador continuo 𝒟 del prior discreto D. Ruido suficientemente suave para coordenadas derivadas.','dynamics'],['Máxima entropía','p(x)\\propto\\exp\\!\\left(-\\sum_k\\lambda_k f_k(x)\\right)','Distribución menos comprometida bajo restricciones explícitas y medida base.','information']
];
function atlasPage(){const query=state.atlasQuery.toLowerCase();return `<section class="page-head"><div><span class="eyebrow green">COMPRESIÓN / REFERENCIA</span><h1>Atlas matemático</h1><p>Notación, ecuaciones y supuestos. Una referencia compacta para volver al libro.</p></div><button class="btn" data-start="diagnostic">Calibrar mi punto de partida</button></section><div class="atlas-search"><label for="atlas-search">Buscar en ecuaciones y misiones</label><input type="search" id="atlas-search" value="${esc(state.atlasQuery)}" placeholder="Bayes, gradiente, precisión, energía libre…"></div><div id="atlas-results">${atlasResults(query)}</div><section class="dependency-section"><span class="eyebrow">DEPENDENCIAS / RAMAS</span><h2>Una ruta para cada objetivo.</h2><div class="route-cards"><article class="panel"><span class="tag green">TRONCO</span><h3>Leer las ecuaciones centrales</h3><p>Lenguaje → Probabilidad → Estadística → Bayes → Información → Álgebra lineal → cápsula de gradiente → Variacional → Modelos generativos.</p></article><article class="panel"><span class="tag orange">DISCRETO / CAP. 7</span><h3>Actuar con estados ocultos</h3><p>Modelos generativos → POMDP → políticas → G → aprendizaje de matrices → agente integrado.</p></article><article class="panel"><span class="tag cyan">CONTINUO / CAP. 8</span><h3>Percepción como dinámica</h3><p>Diferencial → Integral → Varias variables → Dinámica → precisión, Laplace y errores de predicción.</p></article></div><div class="dependency-list">${WORLDS.map(w=>`<div><button class="text-button" data-world="${w.id}" style="color:${w.color}">${w.symbol} ${w.name}</button><span>${w.prereq.length?w.prereq.map(p=>world(p).name).join(' + '):'Primeros principios'}</span></div>`).join('')}</div></section><section class="sources-section"><span class="eyebrow">BIBLIOTECA / TRAZABILIDAD</span><h2>Construido sobre tus materiales.</h2><p class="muted">Síntesis original de los materiales locales de ENIGMA. Las referencias orientan la lectura; el juego no reproduce los PDFs ni sustituye el libro.</p><div class="source-grid">${SOURCES.map(s=>`<article class="panel"><span class="tag">${s.kind}</span><h3>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}</h3><p>${esc(s.detail)}</p></article>`).join('')}</div><p class="source-note">Visualizaciones originales en SVG. KaTeX para notación matemática, licencia MIT. Inspiración geométrica de 3Blue1Brown; no se usa su marca ni se copian sus escenas. Nats por defecto; las equivalencias F/G incluyen su convención y supuestos.</p></section>`;}
function atlasResults(query){const gs=glossary.filter(g=>!query||g.join(' ').toLowerCase().includes(query)),ls=query?LESSONS.filter(l=>`${l.title} ${l.subtitle} ${l.world}`.toLowerCase().includes(query)):[];return `${ls.length?`<div class="search-missions">${ls.map(l=>`<button class="related-chip" data-lesson="${l.id}">${esc(l.title)}</button>`).join('')}</div>`:''}<div class="equation-grid">${gs.map(([title,formula,assumption,w])=>`<article class="equation-card panel"><div><span class="eyebrow">${world(w).name}</span><button class="text-button" data-world="${w}">Estudiar</button></div><h3>${title}</h3><div class="formula">${math(formula,true)}</div><p>${assumption}</p></article>`).join('')||'<div class="empty-state panel"><p>No hay coincidencias. Prueba otra palabra.</p></div>'}</div>`;}
function settingsPage(){const h=profile.history.slice(-14);return `<section class="page-head"><div><span class="eyebrow green">BITÁCORA / CONFIGURACIÓN</span><h1>Tu expedición, en perspectiva.</h1><p>El progreso se guarda en este navegador. Exporta una copia para trasladarlo o respaldarlo.</p></div><button class="btn" id="export-btn">Exportar bitácora</button></section><div class="review-summary"><div>${profile.xp}<span>XP acumulados</span></div><div>${totalMastered()} / ${LESSONS.length}<span>misiones dominadas</span></div><div>${profile.badges.length}<span>mundos acreditados por salto</span></div></div><div class="settings-grid"><section class="panel settings-panel"><span class="eyebrow">PRÁCTICA RECIENTE</span><h2>Las ideas se consolidan al volver.</h2>${h.length?`<div class="activity-chart">${h.map(e=>`<div><i style="height:${Math.max(8,e.correct/e.total*110)}px"></i><span>${e.correct}/${e.total}</span><small>${esc(e.date.slice(5))}</small></div>`).join('')}</div>`:'<p class="muted">Tu actividad aparecerá después del primer desafío.</p>'}<div class="badge-list">${profile.badges.map(w=>`<span class="related-chip">${world(w).symbol} ${world(w).name} ✓</span>`).join('')}</div></section><section class="panel settings-panel"><span class="eyebrow">AJUSTES</span><div class="setting-row"><div><strong>Feedback sonoro</strong><p>Tonos breves al comprobar una respuesta.</p></div><input type="checkbox" id="sound-toggle" role="switch" aria-label="Feedback sonoro" ${profile.settings.sound?'checked':''}></div><div class="setting-row"><div><strong>Modo compacto</strong><p>Menos espacio entre bloques, mismo contenido.</p></div><input type="checkbox" id="dense-toggle" role="switch" aria-label="Modo compacto" ${profile.settings.dense?'checked':''}></div><div class="setting-row"><div><strong>Importar bitácora</strong><p>Solo archivos JSON exportados por NÓESIS.</p></div><label class="btn import-label" for="import-file">Elegir copia<input type="file" id="import-file" accept="application/json,.json" hidden></label></div><p class="muted">Al importar, el progreso actual se reemplaza después de tu confirmación. No se envía al servidor; no se sincroniza entre dispositivos.</p><div class="reset-row"><button class="text-button danger" id="reset-btn">Reiniciar progreso</button></div></section></div><div class="review-explain"><h3>Qué significa dominio en este juego.</h3><p>Una misión acredita con 3 de 4 respuestas sin ayuda. Una prueba de salto exige 85% sin pistas y cubre una pregunta de transferencia por misión. XP recompensan preguntas nuevas: repetir no permite acumular puntos sin límite. El repaso usa recuperación espaciada; para transferir de verdad, reconstruye derivaciones y contrasta con tus guías.</p></div>`;}
function render(){let html={map:mapPage,lesson:lessonPage,quiz:quizPage,lab:labPage,review:reviewPage,atlas:atlasPage,settings:settingsPage}[state.view]?.()||mapPage();shell(html);if(state.view==='lesson'&&state.tab==='visual'){const l=byId(state.lesson);(VISUALS[l.visual]||VISUALS.function).mount($('#lesson-viz'));}if(state.view==='lab'){VISUALS[state.lab].mount($('#lab-viz'));$('#verify-field').onclick=()=>{const result=FIELD_MISSIONS[state.lab].test($('#lab-viz'));$('#field-feedback').innerHTML=`<strong class="${result.pass?'green':'orange'}">${result.pass?'Objetivo resuelto.':'Sigue ajustando el sistema.'}</strong><p>${esc(result.readout)}</p>`;if(result.pass&&!profile.labBadges.includes(state.lab)){profile.labBadges.push(state.lab);profile.xp+=40;save();$('.xp').textContent=profile.xp+' XP';sound(true);toast('Contrato de campo completado · +40 XP');}};$('#field-clue').onclick=()=>{$('#field-feedback').textContent=FIELD_MISSIONS[state.lab].clue;};}if(state.view==='quiz'){if(session.finished){$('#retry-quiz').onclick=()=>startQuiz(session.kind,session.target);$('#result-map').onclick=()=>{session=null;go('map')};$$('[data-lesson]').forEach(b=>b.onclick=()=>{const id=b.dataset.lesson;session=null;openLesson(id)});}else{$$('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));$('#numeric-form')?.addEventListener('submit',e=>{e.preventDefault();answer($('#numeric-answer').value)});if($('#hint-btn'))$('#hint-btn').onclick=()=>{session.assisted=true;render()};if($('#next-question'))$('#next-question').onclick=nextQuestion;$('#exit-quiz').onclick=()=>go('lesson');}}if(state.view==='atlas')$('#atlas-search').oninput=e=>{state.atlasQuery=e.target.value;$('#atlas-results').innerHTML=atlasResults(state.atlasQuery.toLowerCase());$$('#atlas-results [data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));$$('#atlas-results [data-world]').forEach(b=>b.onclick=()=>{const l=inWorld(b.dataset.world)[0];if(l)openLesson(l.id)});};if(state.view==='settings')bindSettings();}
function bindSettings(){$('#sound-toggle').onchange=e=>{profile.settings.sound=e.target.checked;save();sound(true)};$('#dense-toggle').onchange=e=>{profile.settings.dense=e.target.checked;save();document.body.classList.toggle('dense',profile.settings.dense)};$('#export-btn').onclick=()=>{const blob=new Blob([JSON.stringify(profile,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`noesis-bitacora-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Bitácora exportada.');};$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('La copia supera 2 MB.');const data=validateProfile(JSON.parse(await f.text()));if(confirm(`Importar ${Object.values(data.records).filter(r=>r.mastered).length} misiones dominadas y ${data.xp} XP? Se reemplazará la bitácora actual.`)){profile=data;save();render();toast('Bitácora restaurada.');}}catch(err){toast(err.message||'No se pudo leer esta copia.');}e.target.value='';};$('#reset-btn').onclick=()=>{if(confirm('Reiniciar todos los XP y el dominio? Exporta una copia primero si quieres conservarlos.')){profile=blank();save();state.lesson=LESSONS[0]?.id;render();toast('Expedición reiniciada.');}};}
window.addEventListener('keydown',e=>{if(state.view!=='quiz'||!session||session.finished||e.ctrlKey||e.metaKey||e.altKey)return;if(e.target instanceof HTMLInputElement)return;if(e.key==='Enter'&&session.answered){e.preventDefault();nextQuestion();}else if(/^[1-4]$/.test(e.key)&&!session.answered){const item=session.items[session.index];if(item.q.type==='choice'){e.preventDefault();answer(item.order[+e.key-1]);}}});
function navigateHash(){let hash;try{hash=decodeURIComponent(location.hash.slice(1));}catch{state.view='map';return;}if(hash.startsWith('mission/')){const id=hash.slice(8),l=byId(id)||inWorld(id)[0];if(l){state.view='lesson';state.lesson=l.id;state.world=l.world;}}else if(hash.startsWith('lab/')&&Object.hasOwn(VISUALS,hash.slice(4))){state.view='lab';state.lab=hash.slice(4);}else if(['map','atlas','review','settings'].includes(hash))state.view=hash;}
window.addEventListener('hashchange',()=>{if(state.view==='quiz'&&session&&!session.finished)return;navigateHash();render()});navigateHash();render();
if(document.modelContext?.registerTool){const ctx=document.modelContext;const register=tool=>{try{Promise.resolve(ctx.registerTool(tool)).catch(()=>{})}catch{}};register({name:'read_math_progress',description:'Read local study progress, current view, and due review missions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {mastered:totalMastered(),total:LESSONS.length,xp:profile.xp,due:dueLessons().map(l=>({id:l.id,title:l.title})),view:state.view}}});register({name:'open_math_mission',description:'Open an educational mission in the same interface. Does not submit answers or credit mastery.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.lessonId!=='string'||!byId(input.lessonId))throw Error('Unknown lesson ID');if(session&&!session.finished)throw Error('Finish the active challenge first');openLesson(input.lessonId);return {lessonId:state.lesson,view:state.view}}});}
window.NOESIS={parseNumber,validateProfile,getProgress:()=>JSON.parse(JSON.stringify(profile)),getView:()=>({...state}),contentStats:()=>({worlds:WORLDS.length,lessons:LESSONS.length,questions:LESSONS.reduce((a,l)=>a+l.questions.length,0)})};
})();
